#define sampler_worms sampler_noise_lq
sampler sampler_worms;
vec3 color, mus;
float dx,dy;

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec2 uv1 = (uv-.5) * uAspect.xy;
vec2 uv6 = uv1;
float z = q27*.05*length(uv1)+q30;
vec2 d = normalize(uv1);
vec2 rs = clamp(tan(z)*d,-8, 8.0 );
if (q28 ==1) {rs *= sin(uv * 5.0) ;}
uv += rs*dot(rs,rs) / 60.0;
uv6 = (uv-.5)*(1 + 1.0 * q1*q27);
//uv6 = multiply(uv6,mat2(_qa));
mus = .1/(sqrt(uv6.y-.2));
mus = abs(mus);
mus *= vec3 (.8,.6, 1.0 );
vec3 blur = GetBlur1(fract(uv));
vec3 crisp= texture(sampler_main,uv);
vec3 ret1 = crisp - blur*.05 + .06*mus;
ret = ret1 * .99 -  .01;
  fragColor = vec4(ret, 1.0);
}

